package vn.rtr.aeris.crew02;
import android.os.Build;import android.security.keystore.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.security.cert.*;import java.security.spec.*;import java.math.BigInteger;import java.util.*;import javax.net.ssl.*;import javax.security.auth.x500.X500Principal;
/** Explicit test identity initialization and out-of-band admin pins, never TOFU.
 * TLS signs precomputed digests through NONEwithECDSA; certificate and application proof remain SHA256withECDSA.
 * Legacy key authorization cannot be edited, so tls02 uses an explicit separate alias with no key-manager fallback. */
public final class CrewTrust02{
 public static final String LEGACY_ALIAS="aeris-crew02-server-p256",ALIAS="aeris-crew02-server-p256-tls02",PUBLIC_IDENTITY="public-identity-tls02.json";private final File root;private final CrewAudit02 audit;private Map<String,Object>manifest;private String digest;private X509Certificate nativeCert,peerCert;private KeyStore store;
 public CrewTrust02(File root,CrewAudit02 audit){this.root=root;this.audit=audit;}
 private static byte[]der(String s)throws IOException{try{return Base64.getDecoder().decode(s);}catch(Exception e){throw new IOException("CREW_CERT_BASE64");}}
 public synchronized Map<String,Object>initialize()throws Exception{if(!root.isDirectory()&&!root.mkdirs())throw new IOException("CREW_TRUST_DIR");store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias(ALIAS)){KeyPairGenerator gen=KeyPairGenerator.getInstance(KeyProperties.KEY_ALGORITHM_EC,"AndroidKeyStore");long now=System.currentTimeMillis();gen.initialize(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setAlgorithmParameterSpec(new ECGenParameterSpec("secp256r1")).setDigests(KeyProperties.DIGEST_NONE,KeyProperties.DIGEST_SHA256).setCertificateSubject(new X500Principal("CN=localhost,O=RtR Engineering")).setCertificateSerialNumber(new BigInteger(120,new SecureRandom()).add(BigInteger.ONE)).setCertificateNotBefore(new Date(now-60000)).setCertificateNotAfter(new Date(now+30L*86400000)).build());gen.generateKeyPair();}nativeCert=(X509Certificate)store.getCertificate(ALIAS);validate(nativeCert);PrivateKey k=(PrivateKey)store.getKey(ALIAS,null);Signature sig=Signature.getInstance("SHA256withECDSA");byte[]challenge=new byte[32];new SecureRandom().nextBytes(challenge);sig.initSign(k);sig.update(challenge);byte[]proof=sig.sign();sig.initVerify(nativeCert);sig.update(challenge);if(!sig.verify(proof))throw new IOException("CREW_KEY_POSSESSION");KeyInfo info=(KeyInfo)KeyFactory.getInstance(k.getAlgorithm(),"AndroidKeyStore").getKeySpec(k,KeyInfo.class);Set<String>authorized=new HashSet<>(Arrays.asList(info.getDigests()));if(!authorized.equals(new HashSet<>(Arrays.asList(KeyProperties.DIGEST_NONE,KeyProperties.DIGEST_SHA256))))throw new IOException("CREW_TLS_DIGEST_AUTHORIZATION");byte[]prehashed=MessageDigest.getInstance("SHA-256").digest(challenge);Signature raw=Signature.getInstance("NONEwithECDSA");raw.initSign(k);raw.update(prehashed);byte[]rawProof=raw.sign();raw.initVerify(nativeCert);raw.update(prehashed);if(!raw.verify(rawProof))throw new IOException("CREW_TLS_PREHASHED_KEY_POSSESSION");Object level=Build.VERSION.SDK_INT>=31?info.getSecurityLevel():info.isInsideSecureHardware()?"REPORTED_INSIDE_HARDWARE":"SOFTWARE_OR_UNKNOWN";String pem="-----BEGIN CERTIFICATE-----\n"+Base64.getMimeEncoder(64,new byte[]{10}).encodeToString(nativeCert.getEncoded())+"\n-----END CERTIFICATE-----\n";Map<String,Object>out=Data97.m("certDerBase64",Base64.getEncoder().encodeToString(nativeCert.getEncoded()),"certPem",pem,"certSha256",CrewAudit02.sha(nativeCert.getEncoded()),"spkiSha256",CrewAudit02.sha(nativeCert.getPublicKey().getEncoded()),"securityLevel",level,"alias",ALIAS,"subject",nativeCert.getSubjectX500Principal().getName(),"notBeforeMs",nativeCert.getNotBefore().getTime(),"notAfterMs",nativeCert.getNotAfter().getTime(),"hardwareAttested",false,"authorizedDigests",new TreeSet<>(authorized),"prehashedProofVerified",true,"keyProfile","tls02-none-sha256","legacyAliasRetained",store.containsAlias(LEGACY_ALIAS));writePublic(new File(root,PUBLIC_IDENTITY),Data97.json(out).getBytes(StandardCharsets.UTF_8));return out;}
 private void writePublic(File f,byte[]b)throws Exception{if(Files.isSymbolicLink(f.toPath()))throw new IOException("CREW_PUBLIC_PATH");try(FileOutputStream o=new FileOutputStream(f)){o.write(b);o.getFD().sync();}}
 public static void validate(X509Certificate c)throws Exception{c.checkValidity();if(!c.getPublicKey().getAlgorithm().equals("EC")||!c.getSigAlgName().equalsIgnoreCase("SHA256withECDSA")||!((java.security.interfaces.ECPublicKey)c.getPublicKey()).getParams().getOrder().equals(new BigInteger("ffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551",16)))throw new IOException("CREW_CERT_ALGORITHM");c.verify(c.getPublicKey());boolean[]usage=c.getKeyUsage();if(usage!=null&&!usage[0])throw new IOException("CREW_CERT_KEY_USAGE");}
 public synchronized Map<String,Object>load()throws Exception{if(store==null||nativeCert==null)throw new IOException("CREW_EXPLICIT_KEY_INIT_REQUIRED");File f=new File(root,"admin-trust.json");if(Files.isSymbolicLink(f.toPath())||!f.isFile()||f.length()>16384)throw new IOException("CREW_ADMIN_TRUST_REQUIRED");byte[]b=Files.readAllBytes(f.toPath());validate(nativeCert);Map<String,Object>m=StrictJson02.parse(b);StrictJson02.exact(m,"format","version","realm","aircraft","trustEpoch","nativeSpkiSha256","peerPrincipal","peerCertDerBase64","peerCertSha256","peerSpkiSha256","peerScopes");if(!"aeris-crew02-admin-trust".equals(m.get("format"))||StrictJson02.integer(m,"version")!=1||!"rtr-crew02-test".equals(m.get("realm"))||!"sitl-42".equals(m.get("aircraft"))||!"payload-b".equals(m.get("peerPrincipal"))||!CrewAudit02.sha(nativeCert.getPublicKey().getEncoded()).equals(m.get("nativeSpkiSha256"))||StrictJson02.integer(m,"trustEpoch")<1)throw new IOException("CREW_ADMIN_POLICY_BINDING");X509Certificate peer=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(der(StrictJson02.text(m,"peerCertDerBase64"))));validate(peer);List<String>eku=peer.getExtendedKeyUsage();if(eku!=null&&!eku.contains("1.3.6.1.5.5.7.3.2"))throw new IOException("CREW_CERT_CLIENT_AUTH");if(CrewAudit02.sha(peer.getPublicKey().getEncoded()).equals(m.get("nativeSpkiSha256")))throw new IOException("CREW_DISTINCT_IDENTITY_KEYS_REQUIRED");if(!CrewAudit02.sha(peer.getEncoded()).equals(m.get("peerCertSha256"))||!CrewAudit02.sha(peer.getPublicKey().getEncoded()).equals(m.get("peerSpkiSha256")))throw new IOException("CREW_ADMIN_PEER_PIN");Set<String>scopes=new HashSet<>(Arrays.asList(StrictJson02.text(m,"peerScopes").split(",",-1)));if(scopes.isEmpty()||scopes.size()!=StrictJson02.text(m,"peerScopes").split(",",-1).length||scopes.size()>5||!new HashSet<>(Arrays.asList(PayloadCore97.SCOPES)).containsAll(scopes))throw new IOException("CREW_ADMIN_ROLE_SCOPES");String h=CrewAudit02.sha(b);audit.trust(StrictJson02.integer(m,"trustEpoch"),h);manifest=m;digest=h;peerCert=peer;return new LinkedHashMap<>(m);}
 public synchronized void current()throws Exception{File f=new File(root,"admin-trust.json");if(manifest==null||!f.isFile()||Files.isSymbolicLink(f.toPath())||f.length()>16384||!digest.equals(CrewAudit02.sha(Files.readAllBytes(f.toPath()))))throw new IOException("CREW_TRUST_CHANGED_EXPLICIT_RELOAD_REQUIRED");nativeCert.checkValidity();peerCert.checkValidity();}

 public synchronized SSLServerSocket listener()throws Exception{current();KeyManagerFactory km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(store,null);TrustManager trust=new X509TrustManager(){public X509Certificate[]getAcceptedIssuers(){return new X509Certificate[]{peerCert};}public void checkServerTrusted(X509Certificate[]c,String a)throws CertificateException{throw new CertificateException("CLIENT_CERT_ONLY");}public void checkClientTrusted(X509Certificate[]c,String a)throws CertificateException{try{current();if(c==null||c.length!=1)throw new IOException("CREW_CERT_CHAIN");validate(c[0]);if(!Arrays.equals(peerCert.getEncoded(),c[0].getEncoded()))throw new IOException("CREW_PEER_CERT_PIN");}catch(Exception e){throw new CertificateException(e.getMessage(),e);}}};SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(new KeyManager[]{PinnedServerKeyManager02.select(km.getKeyManagers(),nativeCert)},new TrustManager[]{trust},new SecureRandom());SSLServerSocket server=(SSLServerSocket)ctx.getServerSocketFactory().createServerSocket();server.setReuseAddress(false);server.bind(new java.net.InetSocketAddress("127.0.0.1",5942),2);List<String>allowed=new ArrayList<>();for(String p:server.getSupportedProtocols())if(p.equals("TLSv1.2")||p.equals("TLSv1.3"))allowed.add(p);if(allowed.isEmpty()){server.close();throw new IOException("CREW_TLS_PROTOCOL_UNAVAILABLE");}server.setEnabledProtocols(allowed.toArray(new String[0]));server.setNeedClientAuth(true);return server;}
 public synchronized String nativeFingerprint()throws Exception{if(nativeCert==null)throw new IOException("CREW_KEY_NOT_INITIALIZED");return CrewAudit02.sha(nativeCert.getPublicKey().getEncoded());}
 public synchronized void verifyCurrentPeer02(X509Certificate c)throws Exception{current();if(!Arrays.equals(peerCert.getEncoded(),c.getEncoded()))throw new IOException("CREW_CURRENT_PEER_PIN_REQUIRED");}
 public synchronized Set<String>peerScopes()throws Exception{current();return new HashSet<>(Arrays.asList(StrictJson02.text(manifest,"peerScopes").split(",")));}
}
